func TestCorruptDataRejected(t *testing.T) {
	dir := tempDir(t)
	r := mustCreate(t, dir)
	setupWorld(t, r)
	r.Close()

	if err := os.WriteFile(filepath.Join(dir, "registry.json"), []byte("{not json"), fileMode); err != nil {
		t.Fatal(err)
	}
	if _, err := Open(dir); !errors.Is(err, ErrCorrupt) {
